('robotics_ros2', 'ros-2', 'robotics-framework', 'ROS 2', 'The open Robot Operating System middleware and software ecosystem.', 'ROS 2 provides libraries and tools for building robot applications across research and production systems.', 'Open Robotics', 'US', 'active', 'public', 'open-source', NULL, 'https://docs.ros.org', 'https://github.com/ros2/ros2', 'https://docs.ros.org', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_lerobot', 'lerobot', 'robotics-framework', 'LeRobot', 'An open framework, model hub workflow and tooling stack for end-to-end robot learning.', 'LeRobot makes robotics datasets, policies, training and hardware integrations accessible through an open software stack.', 'Hugging Face', 'FR', 'active', 'public', 'open-source', 'Apache-2.0', 'https://huggingface.co/docs/lerobot', 'https://github.com/huggingface/lerobot', 'https://huggingface.co/docs/lerobot', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_mujoco', 'mujoco', 'simulator', 'MuJoCo', 'An open-source physics engine for robotics, biomechanics and machine learning.', 'MuJoCo is a general-purpose physics simulator focused on articulated systems and contact dynamics.', 'Google DeepMind', 'US', 'active', 'public', 'open-source', 'Apache-2.0', 'https://mujoco.org', 'https://github.com/google-deepmind/mujoco', 'https://mujoco.readthedocs.io', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_isaac_lab', 'isaac-lab', 'simulator', 'Isaac Lab', 'A unified open framework for robot learning built on NVIDIA Isaac Sim.', 'Isaac Lab provides reinforcement learning, imitation learning and motion-planning workflows for simulated robots.', 'NVIDIA', 'US', 'active', 'public', 'open-source', 'BSD-3-Clause', 'https://isaac-sim.github.io/IsaacLab', 'https://github.com/isaac-sim/IsaacLab', 'https://isaac-sim.github.io/IsaacLab', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_unitree_sdk2', 'unitree-sdk2', 'robotics-framework', 'Unitree SDK2', 'The official open SDK for developing applications on current Unitree robots.', 'Unitree SDK2 exposes control and application interfaces for several Unitree quadruped and humanoid platforms.', 'Unitree Robotics', 'CN', 'active', 'public', 'open-source', 'BSD-3-Clause', 'https://support.unitree.com/home/zh/developer', 'https://github.com/unitreerobotics/unitree_sdk2', 'https://support.unitree.com/home/zh/developer', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_reachy2', 'reachy-2', 'robot', 'Reachy 2', 'A humanoid robot platform from Pollen Robotics with an open Python SDK and simulation path.', 'Reachy 2 is a physical robot platform. Its SDK is open; hardware openness is tracked as a separate, currently incomplete facet.', 'Pollen Robotics', 'FR', 'active', 'public', 'open-core', 'Apache-2.0', 'https://www.pollen-robotics.com/reachy-2', 'https://github.com/pollen-robotics/reachy2-sdk', 'https://pollen-robotics.github.io/reachy2-sdk', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_genesis', 'genesis-world', 'simulator', 'Genesis', 'An open simulation platform for general-purpose robotics and embodied AI learning.', 'Genesis provides a physics and simulation environment for robot learning and embodied intelligence research.', 'Genesis Embodied AI', NULL, 'active', 'public', 'open-source', 'Apache-2.0', 'https://genesis-world.readthedocs.io', 'https://github.com/Genesis-Embodied-AI/genesis-world', 'https://genesis-world.readthedocs.io', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_openpi', 'openpi', 'model', 'openpi', 'Open-source robot policy models and software from Physical Intelligence.', 'openpi provides robot policy model code and checkpoints for research and evaluation in physical intelligence.', 'Physical Intelligence', 'US', 'active', 'public', 'open-source', 'Apache-2.0', 'https://www.physicalintelligence.company', 'https://github.com/Physical-Intelligence/openpi', NULL, '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
('robotics_openarm', 'openarm', 'robot', 'OpenArm', 'A fully open-source humanoid arm for physical AI research and contact-rich deployment.', 'OpenArm publishes robot hardware and software resources for reproducible manipulation research.', 'Enactic', NULL, 'active', 'public', 'open-source', 'Apache-2.0', 'https://openarm.dev', 'https://github.com/enactic/openarm', 'https://openarm.dev', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z', '2026-08-22T00:00:00.000Z'),
